import * as PIXI from 'pixi.js';
import { PIXEL_FX, type PixelFxMeta, type PixelFxSlug } from '../../pixelFx.generated';
import { publicAsset } from '../../../utils/publicAsset';

export interface PixelFxPlayOptions {
  /** Multiplier on the effect's native pixel size. */
  scale?: number;
  alpha?: number;
  /** Mirror horizontally (effects are authored facing right). */
  flipX?: boolean;
  tint?: number;
  zIndex?: number;
}

/**
 * Sprite-based effects generated by pixelfx (scripts/vfx/).
 *
 * Each effect ships as one horizontal strip, so a sheet becomes N textures that
 * PIXI.AnimatedSprite can play back at the effect's authored frame rate. The
 * layer keeps textures cached per slug: the first shot pays the decode cost,
 * every shot after it is a sprite allocation.
 */
export class PixelFxLayer {
  public readonly container = new PIXI.Container();
  private readonly sheets = new Map<string, PIXI.Texture[]>();
  private readonly active = new Set<PIXI.AnimatedSprite>();
  private readonly warned = new Set<string>();

  constructor() {
    this.container.eventMode = 'none';
    this.container.sortableChildren = true;
  }

  /** Warm the texture cache before the first shot needs it. */
  public preload(slugs: readonly PixelFxSlug[]): void {
    for (const slug of slugs) this.framesFor(slug);
  }

  private framesFor(slug: string): PIXI.Texture[] | null {
    const cached = this.sheets.get(slug);
    if (cached) return cached;

    const meta = (PIXEL_FX as Record<string, PixelFxMeta>)[slug];
    if (!meta) {
      if (!this.warned.has(slug)) {
        this.warned.add(slug);
        console.warn(`[pixelfx] no generated effect named "${slug}" — run npm run vfx`);
      }
      return null;
    }

    // One base texture for the strip; each frame is a sub-rectangle of it.
    const base = PIXI.Texture.from(publicAsset(`/sprites/vfx/${slug}/strip.png`));
    const frames: PIXI.Texture[] = [];
    for (let i = 0; i < meta.frames; i += 1) {
      frames.push(
        new PIXI.Texture(
          base.baseTexture,
          new PIXI.Rectangle(i * meta.frameWidth, 0, meta.frameWidth, meta.frameHeight),
        ),
      );
    }
    this.sheets.set(slug, frames);
    return frames;
  }

  /**
   * Spawn an effect at a screen-space point (the same space the renderer's
   * particles and traces use, which the camera transform then moves).
   */
  public play(
    slug: PixelFxSlug,
    x: number,
    y: number,
    options: PixelFxPlayOptions = {},
  ): PIXI.AnimatedSprite | null {
    const frames = this.framesFor(slug);
    if (!frames) return null;
    const meta = (PIXEL_FX as Record<string, PixelFxMeta>)[slug];

    const sprite = new PIXI.AnimatedSprite(frames);
    const scale = options.scale ?? 1;
    // The pivot is where the effect's origin sits inside its frame, so anchoring
    // there keeps muzzle smoke on the muzzle and impact grit on the wall.
    sprite.anchor.set(meta.pivot[0] / meta.frameWidth, meta.pivot[1] / meta.frameHeight);
    sprite.position.set(x, y);
    sprite.scale.set(options.flipX ? -scale : scale, scale);
    sprite.alpha = options.alpha ?? 1;
    sprite.zIndex = options.zIndex ?? y;
    if (options.tint !== undefined) sprite.tint = options.tint;
    sprite.animationSpeed = meta.fps / 60;
    sprite.loop = meta.loop;

    if (meta.loop) {
      // Looping sources are ambient (a bleeding wound, sustained fire). Two
      // cycles is enough to read without leaving sprites alive forever.
      let loops = 0;
      sprite.onLoop = () => {
        loops += 1;
        if (loops >= 2) this.release(sprite);
      };
    } else {
      sprite.onComplete = () => this.release(sprite);
    }

    this.container.addChild(sprite);
    this.active.add(sprite);
    // A shotgun blast can exceed this in one frame; drop the oldest instead of
    // letting sustained fire grow the scene graph without bound.
    if (this.active.size > 64) {
      const oldest = this.active.values().next().value;
      if (oldest) this.release(oldest);
    }

    sprite.play();
    return sprite;
  }

  private release(sprite: PIXI.AnimatedSprite): void {
    if (!this.active.delete(sprite)) return;
    sprite.stop();
    sprite.onComplete = undefined;
    sprite.onLoop = undefined;
    if (!sprite.destroyed) sprite.destroy();
  }

  public destroy(): void {
    for (const sprite of [...this.active]) this.release(sprite);
    for (const frames of this.sheets.values()) {
      for (const frame of frames) frame.destroy(false);
    }
    this.sheets.clear();
    this.container.destroy({ children: true });
  }
}
